package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<28)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for sc.Scan() {
		line := strings.TrimSuffix(sc.Text(), "\r")
		var fields []string
		var cur []byte
		inQ := false
		for i := 0; i < len(line); i++ {
			c := line[i]
			if inQ {
				if c == '"' {
					if i+1 < len(line) && line[i+1] == '"' {
						cur = append(cur, '"')
						i++
					} else {
						inQ = false
					}
				} else {
					cur = append(cur, c)
				}
			} else if c == '"' {
				inQ = true
			} else if c == ',' {
				fields = append(fields, string(cur))
				cur = cur[:0]
			} else {
				cur = append(cur, c)
			}
		}
		fields = append(fields, string(cur))
		for i := range fields {
			fields[i] = "[" + fields[i] + "]"
		}
		fmt.Fprintf(w, "%d: %s\n", len(fields), strings.Join(fields, "|"))
	}
}
